String _asciiForPs(String text) {
  const map = <String, String>{
    '\u2550': '=', // box-drawing double horizontal
    '\u2500': '-', // box-drawing light horizontal
    '\u2014': '-', // em dash
    '\u2013': '-', // en dash
    '\u2192': '->', // rightwards arrow
    '\u2714': '[ok]', // check mark
    '\u2718': '[x]', // heavy ballot X
    '\u26a0': '[!]', // warning sign
    '\u2022': '*', // bullet
    '\u2019': "'", // right single quote
